(function(){
  const V3_KEY='gal-scene-project-v3',blobUrls=new Map(),selectedIds=new Set();let layerDrag=null,sceneSaveTimer=null,layerHistoryTimer=null,currentFontCategory='Sans Serif',v3SnapCenter=true,v3SnapGrid=false,sceneHistory=[],sceneHistoryIndex=-1,sceneHistoryLock=false,sceneSnapshots={A:null,B:null},previewScale=1;
  const uid=()=>`layer-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
  const baseLayer=(type,name)=>{const base=defaultConfig();return{id:uid(),name,type,visible:true,locked:false,opacity:1,zIndex:0,transform:{x:0,y:0,scale:1,rotation:0},animations:[],effects:[],interactions:base.interactions,particles:base.particles,entrance:null,exit:null,data:{},asset:null,version:1}};
  function migrate(){try{const saved=JSON.parse(localStorage.getItem(V3_KEY));if(saved?.version===3&&Array.isArray(saved.layers))return saved}catch{}let legacy=config;try{const raw=JSON.parse(localStorage.getItem('gal-project'));if(raw?.asset)legacy={...defaultConfig(),...raw}}catch{}const layers=[];if(legacy.asset){const layer={...baseLayer('image',legacy.asset.name||'Изображение'),...JSON.parse(JSON.stringify(legacy)),id:'legacy-image',type:'image',name:legacy.asset.name||'Изображение',visible:true,locked:false,opacity:1,zIndex:0,data:{assetKey:'current',width:legacy.asset.width,height:legacy.asset.height}};layers.push(layer)}return{version:3,name:legacy.name||'Новая композиция',canvas:{width:1280,height:720,preset:'1280×720',background:'transparent'},layers,selectedLayerId:layers[0]?.id||null,settings:{quality:'medium',grid:10}}}
  let project=migrate();window.galProject=project;
  const iconFor={image:'◇',text:'T',shape:'▭',fx:'✦',emitter:'⁙',group:'▦'};
  const selected=()=>project.layers.find(layer=>layer.id===project.selectedLayerId)||null;
  const layerConfig=layer=>layer;
  function normalizeZ(){project.layers.forEach((layer,index)=>layer.zIndex=index)}
  function selectLayer(id,add=false){if(add){selectedIds.has(id)?selectedIds.delete(id):selectedIds.add(id)}else{selectedIds.clear();selectedIds.add(id)}project.selectedLayerId=id;const layer=selected();if(layer){config=layer;config.name=layer.name;normalizeLayer(layer)}renderLayersPanel();renderScene();renderSelectedEditor();if(layer){particles.getAnchor=()=>{const el=composition.querySelector(`[data-layer-id="${layer.id}"]`),r=el?.getBoundingClientRect()||stage.getBoundingClientRect(),s=stage.getBoundingClientRect();return{x:r.left-s.left+r.width/2,y:r.top-s.top+r.height/2,width:r.width,height:r.height}};particles.setConfig({...layer.particles,count:Math.round(layer.particles.count*({low:.45,medium:.75,high:1}[project.settings.quality]||.75))})}saveScene()}
  function normalizeLayer(layer){const base=defaultConfig();layer.transform={...base.transform,...layer.transform};layer.animations=layer.animations||[];layer.effects=layer.effects||[];layer.interactions={...base.interactions,...layer.interactions,hover:{...base.interactions.hover,...layer.interactions?.hover},click:{...base.interactions.click,...layer.interactions?.click},burst:{...base.interactions.burst,...layer.interactions?.burst}};layer.particles={...base.particles,...layer.particles};layer.opacity=layer.opacity??1;layer.visible=layer.visible!==false;layer.locked=!!layer.locked}
  project.layers.forEach(normalizeLayer);normalizeZ();

  function sceneDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open('game-asset-lab',2);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('assets'))db.createObjectStore('assets');if(!db.objectStoreNames.contains('projects'))db.createObjectStore('projects')};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
  async function putBlob(key,blob){const db=await sceneDb(),tx=db.transaction('assets','readwrite');tx.objectStore('assets').put(blob,key);await new Promise((r,j)=>{tx.oncomplete=r;tx.onerror=()=>j(tx.error)});db.close()}
  async function getBlob(key){const db=await sceneDb(),tx=db.transaction('assets','readonly'),req=tx.objectStore('assets').get(key);return new Promise(resolve=>{req.onsuccess=()=>{db.close();resolve(req.result||null)};req.onerror=()=>resolve(null)})}
  async function deleteBlob(key){try{const db=await sceneDb(),tx=db.transaction('assets','readwrite');tx.objectStore('assets').delete(key);db.close()}catch{}}
  function cleanProject(){const copy=JSON.parse(JSON.stringify(project));copy.layers.forEach(layer=>{if(layer.data)delete layer.data.runtimeUrl});return copy}
  async function saveScene(immediate=false){$('#saveState').textContent='Сохранение…';clearTimeout(sceneSaveTimer);const run=async()=>{try{const clean=cleanProject();localStorage.setItem(V3_KEY,JSON.stringify(clean));const db=await sceneDb(),tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(clean,'current');tx.oncomplete=()=>{db.close();$('#saveState').textContent='Сохранено'};tx.onerror=()=>{$('#saveState').textContent='Ошибка сохранения'}}catch{$('#saveState').textContent='Ошибка сохранения'}};if(immediate)run();else sceneSaveTimer=setTimeout(run,280)}
  async function restoreUrls(){for(const layer of project.layers){if(layer.type==='image'&&layer.data?.assetKey){const blob=await getBlob(layer.data.assetKey);if(blob){const url=URL.createObjectURL(blob);blobUrls.set(layer.id,url)}}if(layer.type==='text'&&layer.data?.customFont){const blob=await getBlob(layer.data.customFont.key);if(blob)try{const face=new FontFace(layer.data.customFont.name,await blob.arrayBuffer());await face.load();document.fonts.add(face)}catch{}}}renderScene()}

  const composition=document.createElement('div');composition.id='compositionRoot';composition.className='composition-root';stage.append(composition);stage.insertAdjacentHTML('beforeend','<div class="scene-guide v" id="guideV"></div><div class="scene-guide h" id="guideH"></div><span class="canvas-size-badge" id="canvasSizeBadge"></span>');root.classList.add('hidden');document.querySelector('.work-area')?.remove();
  function sizeWorkArea(){let work=$('#sceneWorkArea');if(!work){work=document.createElement('div');work.id='sceneWorkArea';work.className='work-area';stage.prepend(work)}const maxW=stage.clientWidth*.78,maxH=stage.clientHeight*.78,ratio=project.canvas.width/project.canvas.height;let w=Math.min(maxW,maxH*ratio),h=w/ratio;if(h>maxH){h=maxH;w=h*ratio}previewScale=w/project.canvas.width;work.style.width=`${w}px`;work.style.height=`${h}px`;composition.style.inset='auto';composition.style.left='50%';composition.style.top='50%';composition.style.width=`${project.canvas.width}px`;composition.style.height=`${project.canvas.height}px`;composition.style.transform=`translate(-50%,-50%) scale(${previewScale})`;composition.style.transformOrigin='center';$('#canvasSizeBadge').textContent=`${project.canvas.width} × ${project.canvas.height} · ${Math.round(previewScale*100)}%`}
  new ResizeObserver(sizeWorkArea).observe(stage);

  function layerTransform(layer){const group=layer.parentId&&project.layers.find(x=>x.id===layer.parentId);const x=layer.transform.x+(group?.transform.x||0),y=layer.transform.y+(group?.transform.y||0),scale=layer.transform.scale*(group?.transform.scale||1),rotation=layer.transform.rotation+(group?.transform.rotation||0);return`translate(-50%,-50%) translate(${x}px,${y}px) scale(${scale}) rotate(${rotation}deg)`}
  function animationFor(layer){const active=layer.animations.filter(x=>x.enabled),items=active.map(a=>{const p=a.params||{},d=p.duration||2;return`v3-${a.type} ${d}s ease-in-out infinite`});if(layer.entrance){const name=layer.entrance.type.toLowerCase().replace(/\s+/g,'-');items.unshift(`v3-enter-${name} ${layer.entrance.duration||.7}s ${layer.entrance.easing||'ease-out'} ${layer.entrance.delay||0}s both`)}return items.join(',')}
  function ensureSceneStyles(){let style=$('#v3-scene-keyframes');if(!style){style=document.createElement('style');style.id='v3-scene-keyframes';document.head.append(style)}style.textContent=`@keyframes v3-float{50%{transform:translateY(-12px)}}@keyframes v3-sway{25%{transform:rotate(7deg)}75%{transform:rotate(-7deg)}}@keyframes v3-pulse{50%{transform:scale(1.09)}}@keyframes v3-breathe{50%{transform:scale(1.06)}}@keyframes v3-bounce{45%{transform:translateY(-20px)}70%{transform:none}}@keyframes v3-shake{25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}@keyframes v3-rotate{to{transform:rotate(360deg)}}@keyframes v3-blink{50%{opacity:.2}}@keyframes v3-drift{35%{transform:translate(14px,-6px)}70%{transform:translate(-8px,5px)}}@keyframes v3-squash{50%{transform:scale(1.12,.88)}}@keyframes v3-enter-fade-in{from{opacity:0}}@keyframes v3-enter-zoom-in{from{opacity:0;transform:scale(.4)}}@keyframes v3-enter-pop{0%{opacity:0;transform:scale(.2)}70%{transform:scale(1.15)}}@keyframes v3-enter-slide-left{from{opacity:0;transform:translateX(-80px)}}@keyframes v3-enter-slide-right{from{opacity:0;transform:translateX(80px)}}@keyframes v3-enter-slide-up{from{opacity:0;transform:translateY(80px)}}@keyframes v3-enter-slide-down{from{opacity:0;transform:translateY(-80px)}}@keyframes v3-enter-bounce-in{0%{opacity:0;transform:translateY(-80px)}70%{transform:translateY(12px)}}@keyframes v3-enter-blur-reveal{from{opacity:0;filter:blur(20px)}}@keyframes v3-enter-glitch-reveal{0%{opacity:0;transform:translateX(20px);filter:hue-rotate(120deg)}70%{transform:translateX(-5px)}}`}
  function renderScene(){ensureSceneStyles();composition.innerHTML='';normalizeZ();project.layers.forEach(layer=>{if(layer.type==='group')return;const el=document.createElement('div');el.className=`scene-layer ${layer.visible?'':'hidden-layer'} ${layer.locked?'locked':''} ${layer.id===project.selectedLayerId?'selected':''}`;el.dataset.layerId=layer.id;el.style.zIndex=layer.zIndex;el.style.opacity=layer.opacity;el.style.transform=layerTransform(layer);const anim=document.createElement('div');anim.className='layer-anim';anim.style.animation=animationFor(layer);const content=renderLayerContent(layer);anim.append(content);el.append(anim);composition.append(el);applyLayerEffects(content,layer);bindSceneLayer(el,layer);bindTestLayer(el,layer)});$('#emptyState').classList.toggle('hidden',project.layers.length>0);sizeWorkArea();renderLayersPanel()}
  function renderLayerContent(layer){const d=layer.data||{};if(layer.type==='image'){const wrap=document.createElement('div');wrap.className='layer-content image-content effect-layer';const image=document.createElement('img');image.alt=layer.name;image.draggable=false;image.src=blobUrls.get(layer.id)||d.runtimeUrl||'';image.style.width=`${d.displayWidth||Math.min(d.width||320,520)}px`;wrap.append(image);return wrap}if(layer.type==='text'){const node=document.createElement('div');node.className=`layer-content text-content ${d.gradient?.enabled?'gradient-text':''} ${d.letterAnimation?`letters-${d.letterAnimation}`:''}`;node.setAttribute('aria-label',d.text||'Текст');node.style.width=`${d.width||480}px`;node.style.fontFamily=`"${d.fontFamily||'Cinzel'}",sans-serif`;node.style.fontSize=`${d.fontSize||64}px`;node.style.setProperty('--font-weight',d.fontWeight||700);node.style.setProperty('--font-style',d.italic?'italic':'normal');node.style.setProperty('--text-decoration',d.underline?'underline':'none');node.style.setProperty('--line-height',d.lineHeight||1.1);node.style.setProperty('--letter-spacing',`${d.letterSpacing||0}px`);node.style.setProperty('--text-align',d.align||'center');node.style.setProperty('--text-transform',d.textTransform||'none');node.style.setProperty('--outline-width',`${d.outline?.width||0}px`);node.style.setProperty('--outline-color',colorAlpha(d.outline?.color||'#000000',d.outline?.opacity??1));node.style.color=d.color||'#ffffff';if(d.gradient?.enabled)node.style.background=d.gradient.type==='radial'?`radial-gradient(circle,${d.gradient.a},${d.gradient.b})`:`linear-gradient(${d.gradient.angle||90}deg,${d.gradient.a},${d.gradient.b})`;node.style.textShadow=textShadow(d);node.style.setProperty('--letter-delay',`${d.letterDelay||.06}s`);setText(node,d);return node}if(layer.type==='shape'){const node=document.createElement('div');node.className=`layer-content shape-content ${d.shape==='line'?'shape-line':''}`;node.style.setProperty('--shape-width',`${d.width||260}px`);node.style.setProperty('--shape-height',`${d.shape==='line'?d.borderWidth||3:d.height||100}px`);node.style.setProperty('--shape-fill',d.gradient?.enabled?`linear-gradient(${d.gradient.angle||90}deg,${d.gradient.a},${d.gradient.b})`:d.fill||'#6e54db');node.style.setProperty('--border-width',`${d.borderWidth||0}px`);node.style.setProperty('--border-color',d.borderColor||'#ffffff');node.style.setProperty('--shape-radius',d.shape==='circle'?'50%':d.shape==='pill'?'999px':`${d.radius||0}px`);node.style.setProperty('--shape-shadow',`${d.shadowX||0}px ${d.shadowY||8}px ${d.shadowBlur||20}px ${d.shadowColor||'#00000088'},0 0 ${d.glow||0}px ${d.glowColor||'#8b5cf6'}`);return node}if(layer.type==='fx'||layer.type==='emitter')return renderFx(layer);const empty=document.createElement('div');empty.className='layer-content';return empty}
  function setText(node,d){const text=d.text||'Новый текст';if(!d.letterAnimation){node.textContent=text;return}if(text.length>500){node.textContent=text;toast('Анимация по буквам отключена: больше 500 символов',true);return}node.innerHTML='';[...text].forEach((char,index)=>{if(char==='\n'){node.append(document.createElement('br'));return}const span=document.createElement('span');span.className='letter';span.style.setProperty('--letter-index',index);span.textContent=char===' '?'\u00a0':char;node.append(span)})}
  function textShadow(d){const shadows=[];if(d.shadow?.enabled)shadows.push(`${d.shadow.x||0}px ${d.shadow.y||4}px ${d.shadow.blur||8}px ${colorAlpha(d.shadow.color||'#000',d.shadow.opacity??.7)}`);if(d.glow?.enabled){const c=d.glow.color||'#8b5cf6',r=d.glow.radius||18;shadows.push(`0 0 ${r*.45}px ${c}`,`0 0 ${r}px ${c}`)}return shadows.join(',')||'none'}
  function colorAlpha(hex,opacity){if(/^#[0-9a-f]{6}$/i.test(hex))return hex+Math.round(opacity*255).toString(16).padStart(2,'0');return hex}
  function applyLayerEffects(content,layer){if(!layer.effects?.length)return;const temp={effects:layer.effects};const s=effectStyles(temp);content.style.filter=s.filter;content.style.opacity=s.opacity;const tint=activeEffects(temp).find(e=>e.type==='tint'),shimmer=activeEffects(temp).find(e=>e.type==='shimmer');if(content.classList.contains('effect-layer')){const img=content.querySelector('img');content.style.setProperty('--asset-mask',`url("${img?.src||''}")`);if(tint){content.classList.add('fx-tint');content.style.setProperty('--tint-color',tint.params.color);content.style.setProperty('--tint-opacity',(tint.params.amount||35)/100)}if(shimmer){content.classList.add('fx-shimmer');content.style.setProperty('--shimmer-angle',`${shimmer.params.angle}deg`);content.style.setProperty('--shimmer-width',`${shimmer.params.width}%`);content.style.setProperty('--shimmer-speed',`${shimmer.params.speed}s`)}}}
  const SYMBOLS={star:'M12 2l2.8 6 6.5.6-4.9 4.3 1.5 6.4L12 17l-5.9 3.3 1.5-6.4-4.9-4.3 6.5-.6z',heart:'M12 21S3 15.4 3 9.5A5 5 0 0112 6a5 5 0 019 3.5C21 15.4 12 21 12 21z',sparkle:'M12 1l2.2 8.8L23 12l-8.8 2.2L12 23l-2.2-8.8L1 12l8.8-2.2z',diamond:'M12 2l8 7-8 13L4 9z',snow:'M11 2h2v20h-2zM3.3 5l1.4-1.4 16 16-1.4 1.4zM20.7 5l-1.4-1.4-16 16L4.7 21z',rune:'M5 20L12 3l7 17-7-5z',lightning:'M14 2L5 13h6l-1 9 9-13h-6z',bubble:'M12 2a10 10 0 100 20 10 10 0 000-20zm-3 4a3 3 0 00-3 3',crown:'M3 18l2-11 5 5 2-8 2 8 5-5 2 11z',flame:'M12 22c-5 0-8-3-7-8 1-4 5-6 6-11 4 3 8 7 8 12 0 4-3 7-7 7z',moon:'M18 17a8 8 0 01-9-12 8.5 8.5 0 1010 11z',sun:'M12 5a7 7 0 110 14 7 7 0 010-14zm-1-5h2v4h-2zm0 20h2v4h-2z',cross:'M10 2h4v8h8v4h-8v8h-4v-8H2v-4h8z',coin:'M12 2a10 10 0 100 20 10 10 0 000-20zm0 4l5 6-5 6-5-6z',key:'M14 3a7 7 0 00-6 10l-6 6v3h4l2-2h3l2-2-2-2 2-2a7 7 0 001-11z',lock:'M6 10V7a6 6 0 0112 0v3h2v12H4V10zm4 0h4V7a2 2 0 00-4 0z',pixel:'M4 4h16v16H4z',droplet:'M12 2s7 8 7 13a7 7 0 11-14 0c0-5 7-13 7-13z',arrow:'M4 10h11l-4-4 3-3 9 9-9 9-3-3 4-4H4z'};
  const svg=(symbol,cls='svg-symbol')=>{const ns='http://www.w3.org/2000/svg',node=document.createElementNS(ns,'svg');node.setAttribute('viewBox','0 0 24 24');node.setAttribute('class',cls);const path=document.createElementNS(ns,'path');path.setAttribute('d',SYMBOLS[symbol]||SYMBOLS.sparkle);node.append(path);return node};
  function renderFx(layer){const d=layer.data,node=document.createElement('div');node.className=`layer-content fx-content ${d.mode==='field'?'symbol-field':''}`;const count=Math.min(d.count||12,80);if(d.mode==='orbit'){for(let i=0;i<count;i++){const item=document.createElement('span');item.className='orbit-item';item.style.setProperty('--orbit-radius',`${d.radius||100}px`);item.style.setProperty('--orbit-speed',`${(d.speed||6)*(d.direction==='reverse'?-1:1)}s`);item.style.setProperty('--ellipse',d.ellipse||1);item.style.transform=`rotate(${(360/count)*i+(d.offset||0)}deg)`;const symbol=svg(d.symbol);symbol.style.setProperty('--symbol-size',`${d.size||18}px`);symbol.style.setProperty('--symbol-color',d.color||'#b99cff');item.append(symbol);node.append(item)}}else{for(let i=0;i<count;i++){const symbol=svg(d.symbol);symbol.style.setProperty('--symbol-size',`${(d.size||18)*(.75+((i*37)%10)/20)}px`);symbol.style.setProperty('--symbol-color',d.color||'#b99cff');symbol.style.setProperty('--symbol-speed',`${(d.speed||3)*(.8+((i*17)%10)/12)}s`);symbol.style.setProperty('--drift-x',`${Math.sin(i*7.3)*(d.spread||180)/2}px`);symbol.style.setProperty('--drift-y',`${Math.sin(i*7.3)*(d.spread||180)/2}px`);symbol.style.left=`${Math.sin(i*7.3)*(d.spread||180)/2}px`;symbol.style.top=`${Math.sin(i*7.3)*(d.spread||180)/2}px`;node.append(symbol)}}return node}

  function bindSceneLayer(el,layer){el.onpointerdown=event=>{event.stopPropagation();selectLayer(layer.id,event.shiftKey);if(layer.locked)return;layerDrag={id:layer.id,x:event.clientX,y:event.clientY,ox:layer.transform.x,oy:layer.transform.y};el.setPointerCapture(event.pointerId)};el.onpointermove=event=>{if(!layerDrag||layerDrag.id!==layer.id)return;layer.transform.x=layerDrag.ox+(event.clientX-layerDrag.x)/previewScale;layer.transform.y=layerDrag.oy+(event.clientY-layerDrag.y)/previewScale;const nearX=Math.abs(layer.transform.x)<10,nearY=Math.abs(layer.transform.y)<10;$('#guideV').classList.toggle('show',nearX);$('#guideH').classList.toggle('show',nearY);if(nearX&&v3SnapCenter)layer.transform.x=0;if(nearY&&v3SnapCenter)layer.transform.y=0;el.style.transform=layerTransform(layer)};el.onpointerup=()=>{if(layerDrag){layerDrag=null;$('#guideV').classList.remove('show');$('#guideH').classList.remove('show');if(v3SnapGrid){layer.transform.x=Math.round(layer.transform.x/10)*10;layer.transform.y=Math.round(layer.transform.y/10)*10}sceneChanged()}};el.ondblclick=()=>{if(layer.type==='text')editText(layer)};el.oncontextmenu=event=>{event.preventDefault();selectLayer(layer.id);showContext(event.clientX,event.clientY,layer)}}
  function bindTestLayer(el,layer){const isTest=()=>document.querySelector('[data-mode="test"]')?.classList.contains('active'),base=()=>layerTransform(layer);el.addEventListener('mouseenter',()=>{if(!isTest())return;const h=layer.interactions?.hover||{};el.style.transition='transform .18s,filter .18s';el.style.transform=`${base()} scale(${h.scale||1}) rotate(${h.rotate||0}deg)`;el.style.filter=`brightness(${h.brightness||100}%) drop-shadow(0 0 ${h.glow||0}px #9d7cff)`;if(h.shake)el.querySelector('.layer-anim')?.animate([{translate:'-4px'},{translate:'4px'},{translate:'0'}],{duration:160,iterations:Infinity});if(h.pulse)el.querySelector('.layer-anim')?.animate([{scale:1},{scale:1.08},{scale:1}],{duration:700,iterations:Infinity})});el.addEventListener('mouseleave',()=>{if(!isTest())return;el.style.transform=base();el.style.filter='';el.querySelectorAll('*').forEach(node=>node.getAnimations?.().forEach(animation=>{if(animation instanceof Animation&&animation.playState==='running'&&animation.effect instanceof KeyframeEffect)animation.cancel()}));renderScene()});el.addEventListener('click',event=>{if(!isTest())return;event.stopPropagation();const c=layer.interactions?.click||{};if(c.burst){selectLayer(layer.id);particles.burst(layer.interactions.burst)}if(c.flash)el.animate([{filter:'brightness(1)'},{filter:'brightness(3)'},{filter:'brightness(1)'}],{duration:320});if(c.bounce||c.squash||c.shake){const mid=c.shake?'translateX(8px)':c.squash?'scale(.84,1.16)':'translateY(-22px)';el.querySelector('.layer-anim')?.animate([{transform:'none'},{transform:mid},{transform:'none'}],{duration:520,easing:'ease-out'})}badge(`${layer.name}: Click`)})}
  stage.addEventListener('pointerdown',event=>{if(event.target===stage||event.target.id==='compositionRoot'){project.selectedLayerId=null;selectedIds.clear();renderScene();renderLayersPanel()}});

  function installLayersUi(){const future=document.querySelector('.future-tools');future.insertAdjacentHTML('beforebegin','<button class="add-object" id="addObjectBtn">＋ Добавить объект</button><section class="layers-panel"><div class="layers-title"><span>СЛОИ</span><span><button id="importProjectBtn" title="Импорт проекта">↥</button><button id="groupLayersBtn" title="Сгруппировать выбранные">▦ Group</button></span></div><div class="layer-list" id="layerList"></div></section>');$('#addObjectBtn').onclick=openAddMenu;$('#groupLayersBtn').onclick=groupSelected;$('#importProjectBtn').onclick=importProjectFile;const transformButton=document.querySelector('[data-section="transform"]');transformButton.innerHTML='<span>▤</span>Слои';transformButton.dataset.section='layers'}
  function renderLayersPanel(){const list=$('#layerList');if(!list)return;list.innerHTML=project.layers.length?[...project.layers].reverse().map(layer=>`<div class="layer-row ${layer.id===project.selectedLayerId?'selected':''} ${selectedIds.has(layer.id)&&layer.id!==project.selectedLayerId?'multi':''}" draggable="true" data-layer-row="${layer.id}"><button class="${layer.visible?'on':''}" data-layer-visible="${layer.id}" title="Показать/скрыть">${layer.visible?'◉':'○'}</button><button class="${layer.locked?'on':''}" data-layer-lock="${layer.id}" title="Блокировка">${layer.locked?'◆':'◇'}</button><span class="layer-kind">${iconFor[layer.type]||'•'}</span><span class="layer-name">${layer.name}</span><span class="layer-actions"><button data-layer-duplicate="${layer.id}">⧉</button><button data-layer-delete="${layer.id}">×</button></span></div>`).join(''):'<div class="layers-empty">Добавьте изображение, текст или фигуру</div>';list.querySelectorAll('[data-layer-row]').forEach(row=>{row.onclick=e=>{if(!e.target.closest('button'))selectLayer(row.dataset.layerRow,e.shiftKey)};row.ondblclick=()=>renameLayer(project.layers.find(x=>x.id===row.dataset.layerRow));row.ondragstart=()=>{layerDrag=row.dataset.layerRow;row.classList.add('dragging')};row.ondragend=()=>row.classList.remove('dragging');row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();reorderLayer(layerDrag,row.dataset.layerRow)}});list.querySelectorAll('[data-layer-visible]').forEach(b=>b.onclick=()=>{const l=project.layers.find(x=>x.id===b.dataset.layerVisible);l.visible=!l.visible;sceneChanged()});list.querySelectorAll('[data-layer-lock]').forEach(b=>b.onclick=()=>{const l=project.layers.find(x=>x.id===b.dataset.layerLock);l.locked=!l.locked;sceneChanged()});list.querySelectorAll('[data-layer-duplicate]').forEach(b=>b.onclick=()=>duplicateLayer(b.dataset.layerDuplicate));list.querySelectorAll('[data-layer-delete]').forEach(b=>b.onclick=()=>deleteLayer(b.dataset.layerDelete))}
  function reorderLayer(fromId,toId){const from=project.layers.findIndex(x=>x.id===fromId),to=project.layers.findIndex(x=>x.id===toId);if(from<0||to<0)return;const [moving]=project.layers.splice(from,1);project.layers.splice(to,0,moving);sceneChanged()}
  function duplicateLayer(id){const source=project.layers.find(x=>x.id===id);if(!source)return;const copy=JSON.parse(JSON.stringify(source));copy.id=uid();copy.name=`${source.name} — копия`;copy.transform.x+=20;copy.transform.y+=20;if(source.type==='image'){copy.data={...copy.data,assetKey:source.data.assetKey};const url=blobUrls.get(source.id);if(url)blobUrls.set(copy.id,url)}project.layers.splice(project.layers.indexOf(source)+1,0,copy);selectLayer(copy.id);sceneChanged();toast('Слой дублирован')}
  function deleteLayer(id){const layer=project.layers.find(x=>x.id===id);if(!layer)return;openV3Dialog('Удалить слой?',`<p>Слой «${escapeHtml(layer.name)}» будет удалён из композиции.</p>`,[{label:'Отмена',action:closeV3Dialog},{label:'Удалить',primary:true,action:()=>{project.layers=project.layers.filter(x=>x.id!==id&&x.parentId!==id);if(layer.type==='image'&&layer.data.assetKey&&!project.layers.some(x=>x.data?.assetKey===layer.data.assetKey))deleteBlob(layer.data.assetKey);project.selectedLayerId=project.layers.at(-1)?.id||null;closeV3Dialog();sceneChanged();toast('Layer удалён')}}])}
  function moveLayer(id,action){const index=project.layers.findIndex(x=>x.id===id);if(index<0)return;if(action==='front'){const [l]=project.layers.splice(index,1);project.layers.push(l)}if(action==='back'){const [l]=project.layers.splice(index,1);project.layers.unshift(l)}if(action==='up'&&index<project.layers.length-1)[project.layers[index],project.layers[index+1]]=[project.layers[index+1],project.layers[index]];if(action==='down'&&index>0)[project.layers[index],project.layers[index-1]]=[project.layers[index-1],project.layers[index]];sceneChanged()}
  function groupSelected(){const ids=[...selectedIds];if(ids.length<2){toast('Выберите минимум два слоя через Shift + клик',true);return}const group=baseLayer('group','Новая группа');group.data={childIds:ids};project.layers.push(group);ids.forEach(id=>{const layer=project.layers.find(x=>x.id===id);if(layer)layer.parentId=group.id});selectLayer(group.id);sceneChanged();toast('Слои сгруппированы')}

  function openAddMenu(){openV3Dialog('Добавить объект','<div class="add-menu"><button data-add-type="image">◇<br>Изображение</button><button data-add-type="text">T<br>Текст</button><button data-add-type="shape">▭<br>Фигура</button><button data-add-type="fx">✦<br>FX-элемент</button></div>',[{label:'Закрыть',action:closeV3Dialog}]);document.querySelectorAll('[data-add-type]').forEach(button=>button.onclick=()=>{const type=button.dataset.addType;if(type==='image'){$('#fileInput').click();closeV3Dialog()}if(type==='text'){closeV3Dialog();addText()}if(type==='shape'){closeV3Dialog();addShape()}if(type==='fx'){closeV3Dialog();addFx()}})}
  function importProjectFile(){const input=document.createElement('input');input.type='file';input.accept='.json,.gal.json,application/json';input.onchange=async()=>{try{const parsed=JSON.parse(await input.files[0].text());if(parsed.version!==3||!Array.isArray(parsed.layers)||!parsed.canvas)throw Error();sceneHistoryLock=true;project=parsed;window.galProject=project;project.layers.forEach(normalizeLayer);const layer=selected();if(layer)config=layer;sceneHistoryLock=false;pushSceneHistory();renderScene();renderSelectedEditor();saveScene(true);toast('Проект импортирован. Изображения выберите повторно, если они отсутствуют.')}catch{toast('Некорректный файл проекта',true)}};input.click()}
  async function addImageFile(file){try{const loaded=await loadAsset(file),layer=baseLayer('image',file.name),key=`asset-${layer.id}`;layer.asset=loaded.meta;layer.data={assetKey:key,width:loaded.meta.width,height:loaded.meta.height,displayWidth:Math.min(loaded.meta.width,520)};project.layers.push(layer);blobUrls.set(layer.id,loaded.url);await putBlob(key,file);selectLayer(layer.id);sceneChanged();toast('Изображение добавлено как слой')}catch(error){toast(error.message,true)}}
  function addText(text='GAME TITLE'){const layer=baseLayer('text','Текст');layer.data={text,width:520,align:'center',fontFamily:'Cinzel',fontSize:64,fontWeight:700,italic:false,underline:false,lineHeight:1.05,letterSpacing:2,textTransform:'none',color:'#ffffff',gradient:{enabled:true,type:'linear',a:'#ffffff',b:'#9b7cff',angle:90},outline:{width:1,color:'#5c3cc9',opacity:1},shadow:{enabled:true,x:0,y:6,blur:14,color:'#000000',opacity:.65},glow:{enabled:true,color:'#8b5cf6',radius:18,strength:70},letterAnimation:'',letterDelay:.06};project.layers.push(layer);loadGoogleFont('Cinzel');selectLayer(layer.id);sceneChanged()}
  function addShape(){const layer=baseLayer('shape','Скруглённая панель');layer.transform.y=100;layer.data={shape:'rounded',width:300,height:110,fill:'#332564',radius:24,borderWidth:1,borderColor:'#745de0',gradient:{enabled:true,a:'#392668',b:'#151b35',angle:135},shadowX:0,shadowY:12,shadowBlur:28,shadowColor:'#00000088',glow:12,glowColor:'#6f55dc'};project.layers.unshift(layer);selectLayer(layer.id);sceneChanged()}
  function addFx(){const layer=baseLayer('fx','Stars Orbit');layer.data={mode:'orbit',symbol:'star',count:10,size:18,color:'#c9b8ff',radius:125,speed:7,direction:'normal',ellipse:1,offset:0,parentId:null,spawn:'around',spread:200};project.layers.push(layer);selectLayer(layer.id);sceneChanged()}

  function renderSelectedEditor(){const layer=selected();if(!layer)return;if(section==='layers'||layer.type==='text'||layer.type==='shape'||layer.type==='fx'||layer.type==='group'){section='layers';document.body.className='section-transform';$('#sectionTitle').textContent=layer.type==='text'?'Текст':layer.type==='shape'?'Фигура':layer.type==='fx'?'FX-элемент':layer.type==='group'?'Группа':'Слой';if(layer.type==='text')renderTextEditor(layer);else if(layer.type==='shape')renderShapeEditor(layer);else if(layer.type==='fx')renderFxEditor(layer);else renderCommonEditor(layer)}}
  function commonControls(layer){return`${control('Позиция X','x',layer.transform.x,-640,640,1,'v3transform',' px')}${control('Позиция Y','y',layer.transform.y,-360,360,1,'v3transform',' px')}${control('Масштаб','scale',layer.transform.scale,.1,4,.01,'v3transform','×')}${control('Поворот','rotation',layer.transform.rotation,-180,180,1,'v3transform','°')}${control('Прозрачность','opacity',layer.opacity,0,1,.01,'v3layer','')}`}
  function renderCommonEditor(layer){editor.innerHTML=`<p class="section-note">${iconFor[layer.type]} ${escapeHtml(layer.name)}</p><div class="editor-block"><header><strong>Трансформация</strong></header><div class="controls">${commonControls(layer)}</div></div>`;bindV3Editor(layer)}
  function renderTextEditor(layer){const d=layer.data;editor.innerHTML=`<div class="editor-block"><header><strong>Содержание</strong></header><div class="controls"><div class="control"><label>Текст</label><textarea data-text-value style="width:100%;min-height:70px;background:#0e111a;color:#fff;border:1px solid var(--line);border-radius:5px;padding:7px">${escapeHtml(d.text)}</textarea></div><button class="btn compact" data-font-browser>Шрифт: ${escapeHtml(d.fontFamily)}</button> <button class="btn compact" data-custom-font>Загрузить шрифт</button>${control('Ширина блока','width',d.width,80,1000,1,'v3data',' px')}${control('Размер','fontSize',d.fontSize,8,240,1,'v3data',' px')}${control('Интервал букв','letterSpacing',d.letterSpacing,-5,30,.5,'v3data',' px')}<div class="control"><label>Выравнивание</label><select data-text-select="align"><option value="left">Слева</option><option value="center">По центру</option><option value="right">Справа</option></select></div><div class="control"><label>Регистр</label><select data-text-select="textTransform"><option value="none">Обычный</option><option value="uppercase">UPPERCASE</option><option value="lowercase">lowercase</option></select></div></div></div><div class="editor-block"><header><strong>Цвет и стиль</strong></header><div class="controls"><div class="control"><label>Основной цвет</label><input type="color" data-text-color="color" value="${d.color}"></div><label><input type="checkbox" data-gradient-enabled ${d.gradient.enabled?'checked':''}> Градиент</label><div class="field-row"><input type="color" data-gradient-color="a" value="${d.gradient.a}"><input type="color" data-gradient-color="b" value="${d.gradient.b}"></div>${control('Угол градиента','angle',d.gradient.angle,0,360,1,'v3gradient','°')}${control('Контур','width',d.outline.width,0,12,.5,'v3outline',' px')}<div class="control"><label>Цвет контура</label><input type="color" data-outline-color value="${d.outline.color}"></div><label><input type="checkbox" data-glow-enabled ${d.glow.enabled?'checked':''}> Свечение</label>${control('Радиус свечения','radius',d.glow.radius,0,60,1,'v3glow',' px')}</div></div><div class="editor-block"><header><strong>Анимация по буквам</strong></header><div class="controls"><select data-letter-animation><option value="">Нет</option><option value="typewriter">Typewriter</option><option value="fade">Letter Fade</option><option value="wave">Wave</option><option value="bounce">Bounce Letters</option><option value="blur">Blur Reveal</option></select>${control('Задержка букв','letterDelay',d.letterDelay,.01,.5,.01,'v3data',' c')}</div></div><div class="add-title">СТИЛИ ТЕКСТА</div><div class="text-style-grid">${['Неон','Золото','Серебро','Лёд','Огонь','Магия','Fantasy','Horror','Arcade','Cyberpunk','Hologram','Royal'].map(name=>`<button class="text-style-card" data-text-preset="${name}">${name}</button>`).join('')}</div><div class="editor-block"><header><strong>Трансформация</strong></header><div class="controls">${commonControls(layer)}</div></div>`;editor.querySelector('[data-text-select="align"]').value=d.align;editor.querySelector('[data-text-select="textTransform"]').value=d.textTransform;editor.querySelector('[data-letter-animation]').value=d.letterAnimation;bindV3Editor(layer);bindFontWeight(layer)}
  function renderShapeEditor(layer){const d=layer.data;editor.innerHTML=`<div class="editor-block"><header><strong>Фигура</strong></header><div class="controls"><div class="control"><label>Тип</label><select data-shape-select><option value="rectangle">Rectangle</option><option value="rounded">Rounded Rectangle</option><option value="circle">Circle</option><option value="ellipse">Ellipse</option><option value="pill">Pill</option><option value="line">Line</option></select></div>${control('Ширина','width',d.width,10,1400,1,'v3data',' px')}${control('Высота','height',d.height,2,900,1,'v3data',' px')}<div class="control"><label>Заливка</label><input type="color" data-shape-color="fill" value="${d.fill}"></div>${control('Скругление','radius',d.radius,0,200,1,'v3data',' px')}${control('Толщина рамки','borderWidth',d.borderWidth,0,30,1,'v3data',' px')}<div class="control"><label>Цвет рамки</label><input type="color" data-shape-color="borderColor" value="${d.borderColor}"></div>${control('Свечение','glow',d.glow,0,80,1,'v3data',' px')}</div></div><div class="editor-block"><header><strong>Трансформация</strong></header><div class="controls">${commonControls(layer)}</div></div>`;editor.querySelector('[data-shape-select]').value=d.shape;bindV3Editor(layer)}
  function renderFxEditor(layer){const d=layer.data;editor.innerHTML=`<div class="editor-block"><header><strong>FX Elements</strong></header><div class="controls"><div class="control"><label>Система</label><select data-fx-select="mode"><option value="orbit">Orbit</option><option value="field">Symbols / Emitter</option><option value="burst">Burst</option><option value="trail">Trail</option></select></div><div class="control"><label>Символ</label><select data-fx-select="symbol">${Object.keys(SYMBOLS).map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div><div class="control"><label>Привязать к</label><select data-fx-parent><option value="">Scene</option>${project.layers.filter(x=>x.id!==layer.id&&x.type!=='fx').map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></div>${control('Количество','count',d.count,1,80,1,'v3data')}${control('Размер','size',d.size,4,80,1,'v3data',' px')}<div class="control"><label>Цвет</label><input type="color" data-fx-color value="${d.color}"></div>${d.mode==='orbit'?`${control('Радиус','radius',d.radius,10,500,1,'v3data',' px')}${control('Скорость','speed',d.speed,.5,30,.5,'v3data',' c')}${control('Эллипс','ellipse',d.ellipse,.2,2,.05,'v3data','×')}`:control('Разброс','spread',d.spread,20,800,1,'v3data',' px')}<button class="btn compact" data-preview-burst>▶ Запустить Burst</button></div></div><div class="editor-block"><header><strong>Трансформация</strong></header><div class="controls">${commonControls(layer)}</div></div>`;editor.querySelector('[data-fx-select="mode"]').value=d.mode;editor.querySelector('[data-fx-select="symbol"]').value=d.symbol;editor.querySelector('[data-fx-parent]').value=layer.parentId||'';bindV3Editor(layer)}
  function bindV3Editor(layer){editor.querySelectorAll('input[type=range]').forEach(input=>input.oninput=()=>{const [kind]=input.dataset.change.split(':');const key=input.dataset.key,value=+input.value;if(kind==='v3transform')layer.transform[key]=value;if(kind==='v3layer')layer[key]=value;if(kind==='v3data')layer.data[key]=value;if(kind==='v3gradient')layer.data.gradient[key]=value;if(kind==='v3outline')layer.data.outline[key]=value;if(kind==='v3glow')layer.data.glow[key]=value;input.previousElementSibling?.querySelector('output')&&(input.previousElementSibling.querySelector('output').textContent=input.value);sceneChanged(false)});editor.querySelector('[data-text-value]')?.addEventListener('input',e=>{layer.data.text=e.target.value;sceneChanged(false)});editor.querySelectorAll('[data-text-select]').forEach(x=>x.onchange=()=>{layer.data[x.dataset.textSelect]=x.value;sceneChanged()});editor.querySelectorAll('[data-text-color]').forEach(x=>x.oninput=()=>{layer.data[x.dataset.textColor]=x.value;sceneChanged(false)});editor.querySelector('[data-gradient-enabled]')?.addEventListener('change',e=>{layer.data.gradient.enabled=e.target.checked;sceneChanged()});editor.querySelectorAll('[data-gradient-color]').forEach(x=>x.oninput=()=>{layer.data.gradient[x.dataset.gradientColor]=x.value;sceneChanged(false)});editor.querySelector('[data-outline-color]')?.addEventListener('input',e=>{layer.data.outline.color=e.target.value;sceneChanged(false)});editor.querySelector('[data-glow-enabled]')?.addEventListener('change',e=>{layer.data.glow.enabled=e.target.checked;sceneChanged()});editor.querySelector('[data-letter-animation]')?.addEventListener('change',e=>{layer.data.letterAnimation=e.target.value;sceneChanged()});editor.querySelector('[data-font-browser]')?.addEventListener('click',()=>openFontBrowser(layer));editor.querySelector('[data-custom-font]')?.addEventListener('click',()=>openCustomFont(layer));editor.querySelectorAll('[data-text-preset]').forEach(x=>x.onclick=()=>applyTextPreset(layer,x.dataset.textPreset));editor.querySelector('[data-shape-select]')?.addEventListener('change',e=>{layer.data.shape=e.target.value;sceneChanged()});editor.querySelectorAll('[data-shape-color]').forEach(x=>x.oninput=()=>{layer.data[x.dataset.shapeColor]=x.value;sceneChanged(false)});editor.querySelectorAll('[data-fx-select]').forEach(x=>x.onchange=()=>{layer.data[x.dataset.fxSelect]=x.value;renderSelectedEditor();sceneChanged()});editor.querySelector('[data-fx-parent]')?.addEventListener('change',e=>{layer.parentId=e.target.value||null;sceneChanged()});editor.querySelector('[data-fx-color]')?.addEventListener('input',e=>{layer.data.color=e.target.value;sceneChanged(false)});editor.querySelector('[data-preview-burst]')?.addEventListener('click',()=>previewBurst(layer))}
  function applyTextPreset(layer,name){const d=layer.data,presets={Неон:['#70f4ff','#1466ff','#4de2e8'],Золото:['#fff0a3','#b76c12','#ffd65c'],Серебро:['#ffffff','#7f8b9e','#dce8ff'],Лёд:['#eaffff','#4aa9ff','#8cecff'],Огонь:['#fff067','#e32919','#ff5a18'],Магия:['#efc8ff','#6235dc','#a768ff'],Fantasy:['#fff3c4','#8d5b24','#d7a95c'],Horror:['#ffdddd','#52000b','#d51c36'],Arcade:['#fff94b','#ff37c7','#5cf4ff'],Cyberpunk:['#55f7ff','#ff2fb3','#51ddec'],Hologram:['#ddffff','#507dff','#86eaff'],Royal:['#fff1a8','#54208f','#bf82ff']};const p=presets[name];d.gradient={enabled:true,type:'linear',a:p[0],b:p[1],angle:90};d.outline={width:2,color:p[2],opacity:1};d.glow={enabled:true,color:p[2],radius:20,strength:75};sceneChanged();renderSelectedEditor();toast(`Стиль «${name}» применён`)}

  function loadGoogleFont(name){if(SYSTEM_FONTS.some(x=>x.name===name))return;const id=`font-${name.replace(/\W/g,'-')}`;if(document.getElementById(id))return;const link=document.createElement('link');link.id=id;link.rel='stylesheet';link.href=`https://fonts.googleapis.com/css2?family=${encodeURIComponent(name).replace(/%20/g,'+')}:wght@300;400;500;600;700;800;900&display=swap`;document.head.append(link);const recent=JSON.parse(localStorage.getItem('gal-recent-fonts')||'[]').filter(x=>x!==name);recent.unshift(name);localStorage.setItem('gal-recent-fonts',JSON.stringify(recent.slice(0,8)))}
  function openFontBrowser(layer){const favorites=JSON.parse(localStorage.getItem('gal-font-favorites')||'[]');openV3Dialog('Библиотека шрифтов',`<div class="field-row"><input id="fontSearch" placeholder="Поиск по 120 шрифтам"><button class="btn compact" id="fontFavorites">⭐</button></div><br><div class="font-browser"><div class="font-categories">${Object.keys(FONT_CATEGORIES).map(cat=>`<button data-font-category="${cat}" class="${cat===currentFontCategory?'active':''}">${cat}</button>`).join('')}</div><div class="font-list" id="fontList"></div></div>`,[{label:'Закрыть',action:closeV3Dialog}]);const renderFonts=(query='')=>{const list=FONT_MANIFEST.filter(font=>(currentFontCategory==='⭐'?favorites.includes(font.name):font.category===currentFontCategory)&&font.name.toLowerCase().includes(query.toLowerCase()));$('#fontList').innerHTML=list.map(font=>`<div class="font-item" data-font-name="${font.name}"><span class="font-sample" style="font-family:'${font.name}'">THE MAGIC CASTLE</span><span class="font-meta">${font.name} · ${font.weights.join(' / ')}</span></div>`).join('')||'<div class="empty-editor">Ничего не найдено</div>';list.forEach(font=>loadGoogleFont(font.name));document.querySelectorAll('[data-font-name]').forEach(item=>item.onclick=()=>{layer.data.fontFamily=item.dataset.fontName;loadGoogleFont(item.dataset.fontName);closeV3Dialog();sceneChanged();renderSelectedEditor()})};renderFonts();document.querySelectorAll('[data-font-category]').forEach(button=>button.onclick=()=>{currentFontCategory=button.dataset.fontCategory;openFontBrowser(layer)});$('#fontSearch').oninput=e=>renderFonts(e.target.value);$('#fontFavorites').onclick=()=>{currentFontCategory='⭐';renderFonts()}}
  function openCustomFont(layer){const input=document.createElement('input');input.type='file';input.accept='.woff,.woff2,.ttf';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Шрифт больше 10 МБ');const name=`Custom-${file.name.replace(/\W/g,'-')}`,face=new FontFace(name,await file.arrayBuffer());await face.load();document.fonts.add(face);await putBlob(`font-${name}`,file);layer.data.fontFamily=name;layer.data.customFont={name,fileName:file.name,key:`font-${name}`};sceneChanged();renderSelectedEditor();toast('Пользовательский шрифт загружен')}catch(error){toast(error.message||'Не удалось загрузить шрифт',true)}};input.click()}
  function previewBurst(layer){const el=composition.querySelector(`[data-layer-id="${layer.id}"]`);if(!el)return;for(let i=0;i<Math.min(layer.data.count||20,50);i++){const s=svg(layer.data.symbol);s.style.position='absolute';s.style.width=s.style.height=`${layer.data.size||18}px`;s.style.fill=layer.data.color;s.style.left='50%';s.style.top='50%';el.append(s);const angle=Math.random()*Math.PI*2,force=50+Math.random()*120;s.animate([{transform:'translate(-50%,-50%) scale(.5)',opacity:1},{transform:`translate(calc(-50% + ${Math.cos(angle)*force}px),calc(-50% + ${Math.sin(angle)*force}px)) rotate(180deg)`,opacity:0}],{duration:700+Math.random()*500,easing:'ease-out'}).onfinish=()=>s.remove()}}
  function editText(layer){openV3Dialog('Редактировать текст',`<textarea id="quickText" style="width:100%;min-height:130px;background:#090c13;color:white;border:1px solid var(--line);padding:10px">${escapeHtml(layer.data.text)}</textarea>`,[{label:'Отмена',action:closeV3Dialog},{label:'Готово',primary:true,action:()=>{layer.data.text=$('#quickText').value;closeV3Dialog();sceneChanged();renderSelectedEditor()}}])}
  function renameLayer(layer){openV3Dialog('Переименовать слой',`<div class="control"><label>Название</label><input id="layerNameInput" type="text" value="${escapeHtml(layer.name)}"></div>`,[{label:'Отмена',action:closeV3Dialog},{label:'Сохранить',primary:true,action:()=>{layer.name=$('#layerNameInput').value.trim()||layer.name;closeV3Dialog();sceneChanged()}}])}
  function showContext(x,y,layer){document.querySelector('.context-menu')?.remove();const menu=document.createElement('div');menu.className='context-menu';menu.style.left=`${Math.min(x,innerWidth-180)}px`;menu.style.top=`${Math.min(y,innerHeight-310)}px`;menu.innerHTML='<button data-c="rename">Переименовать</button><button data-c="duplicate">Дублировать</button><button data-c="up">Выше</button><button data-c="down">Ниже</button><button data-c="front">На передний план</button><button data-c="back">На задний план</button><hr><button data-c="lock">Заблокировать</button><button data-c="hide">Скрыть</button><button data-c="delete">Удалить</button>';document.body.append(menu);menu.querySelectorAll('button').forEach(b=>b.onclick=()=>{const a=b.dataset.c;if(a==='rename')renameLayer(layer);if(a==='duplicate')duplicateLayer(layer.id);if(['up','down','front','back'].includes(a))moveLayer(layer.id,a);if(a==='lock'){layer.locked=!layer.locked;sceneChanged()}if(a==='hide'){layer.visible=false;sceneChanged()}if(a==='delete')deleteLayer(layer.id);menu.remove()});setTimeout(()=>addEventListener('pointerdown',()=>menu.remove(),{once:true}),0)}
  function openV3Dialog(title,content,buttons){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=`<div class="modal-content lab-dialog">${content}<div class="modal-actions">${buttons.map((b,i)=>`<button class="btn ${b.primary?'primary':''}" data-v3-dialog="${i}">${b.label}</button>`).join('')}</div></div>`;$('#modalBackdrop').classList.remove('hidden');buttons.forEach((b,i)=>$(`[data-v3-dialog="${i}"]`).onclick=b.action)}
  function closeV3Dialog(){$('#modalBackdrop').classList.add('hidden')}
  function escapeHtml(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function sceneSnapshot(){return JSON.stringify(cleanProject())}
  function pushSceneHistory(){if(sceneHistoryLock)return;const next=sceneSnapshot();if(sceneHistory[sceneHistoryIndex]===next)return;sceneHistory=sceneHistory.slice(0,sceneHistoryIndex+1);sceneHistory.push(next);if(sceneHistory.length>80)sceneHistory.shift();sceneHistoryIndex=sceneHistory.length-1;updateSceneHistoryButtons()}
  function updateSceneHistoryButtons(){$('#undoBtn').disabled=sceneHistoryIndex<=0;$('#redoBtn').disabled=sceneHistoryIndex>=sceneHistory.length-1;$('#undoBtn').style.opacity=$('#undoBtn').disabled?'.35':'1';$('#redoBtn').style.opacity=$('#redoBtn').disabled?'.35':'1'}
  function restoreSceneHistory(index){if(index<0||index>=sceneHistory.length)return;sceneHistoryLock=true;project=JSON.parse(sceneHistory[index]);window.galProject=project;project.layers.forEach(normalizeLayer);sceneHistoryIndex=index;const layer=selected();if(layer)config=layer;renderScene();renderSelectedEditor();saveScene();sceneHistoryLock=false;updateSceneHistoryButtons();toast('Композиция восстановлена')}
  function sceneChanged(record=true){normalizeZ();renderScene();renderLayersPanel();saveScene();if(record)pushSceneHistory();else{clearTimeout(layerHistoryTimer);layerHistoryTimer=setTimeout(pushSceneHistory,320)}changed();updateSceneHistoryButtons()}

  const baseV3Interactions=renderInteractions;renderInteractions=function(){baseV3Interactions();const layer=selected();if(!layer)return;editor.insertAdjacentHTML('beforeend',`<div class="editor-block"><header><strong>Появление / Исчезновение</strong></header><div class="controls"><div class="control"><label>Entrance</label><select data-entrance><option value="">Нет</option><option>Fade In</option><option>Zoom In</option><option>Pop</option><option>Slide Left</option><option>Slide Right</option><option>Slide Up</option><option>Slide Down</option><option>Bounce In</option><option>Blur Reveal</option><option>Glitch Reveal</option></select></div><div class="control"><label>Exit</label><select data-exit><option value="">Нет</option><option>Fade Out</option><option>Shrink</option><option>Drop</option><option>Slide Away</option><option>Blur Out</option><option>Glitch Out</option><option>Zoom Out</option></select></div></div></div><div class="editor-block"><header><strong>Дополнительный триггер</strong></header><div class="controls"><div class="control"><label>Когда</label><select data-event-when><option>Загрузка сцены</option><option>Hover</option><option>Mouse leave</option><option>Click</option><option>Double click</option><option>Через N секунд</option><option>Manual trigger</option></select></div><div class="control"><label>Действие</label><select data-event-action><option>Play animation</option><option>Restart animation</option><option>Show</option><option>Hide</option><option>Flash</option><option>Shake</option><option>Particle burst</option><option>Start emitter</option><option>Stop emitter</option><option>Play exit animation</option></select></div><button class="btn compact" data-add-event>＋ Добавить действие</button></div></div>`);const entrance=editor.querySelector('[data-entrance]'),exit=editor.querySelector('[data-exit]');entrance.value=layer.entrance?.type||'';exit.value=layer.exit?.type||'';entrance.onchange=()=>{layer.entrance=entrance.value?{type:entrance.value,duration:.7,delay:0,easing:'ease-out'}:null;sceneChanged()};exit.onchange=()=>{layer.exit=exit.value?{type:exit.value,duration:.6,delay:0,easing:'ease-in'}:null;sceneChanged()};editor.querySelector('[data-add-event]').onclick=()=>{layer.events=layer.events||[];layer.events.push({when:editor.querySelector('[data-event-when]').value,action:editor.querySelector('[data-event-action]').value});sceneChanged();toast('Действие добавлено')}};
  const baseV3Presets=renderPresets;renderPresets=function(){baseV3Presets();editor.insertAdjacentHTML('afterbegin',`<div class="add-title">COMPOSITION PRESETS</div><div class="preset-grid"><button class="preset-card large" data-composition-preset="magic"><div class="preset-demo"><i class="mini-crystal"></i></div><strong>✨ Magic Title</strong><small>Text · Gradient · Stars · Glow</small></button><button class="preset-card large" data-composition-preset="neon"><div class="preset-demo"><i class="mini-crystal"></i></div><strong>◈ Neon Title</strong><small>Text · Cyberpunk · Sparkles</small></button><button class="preset-card large" data-composition-preset="gameover"><div class="preset-demo"><i class="mini-crystal"></i></div><strong>☠ Game Over</strong><small>Title · Panel · Horror</small></button><button class="preset-card large" data-composition-preset="start"><div class="preset-demo"><i class="mini-crystal"></i></div><strong>▶ Start Button</strong><small>Shape · Text · Hover</small></button></div>`);editor.querySelectorAll('[data-composition-preset]').forEach(button=>button.onclick=()=>applyCompositionPreset(button.dataset.compositionPreset))};
  function applyCompositionPreset(type){if(type==='start'){addShape();const shape=selected();shape.name='START Button';shape.data.width=320;shape.data.height=96;shape.transform.y=80;addText('START');const text=selected();text.name='START';text.data.fontFamily='Orbitron';text.data.fontSize=42;text.transform.y=80;text.interactions.hover.scale=1.08;loadGoogleFont('Orbitron')}else{addText(type==='gameover'?'GAME OVER':type==='neon'?'NEON DREAM':'MAGIC TITLE');const text=selected();applyTextPreset(text,type==='gameover'?'Horror':type==='neon'?'Cyberpunk':'Магия');text.transform.y=-70;const fx=baseLayer('fx',type==='gameover'?'Runes':'Stars');fx.data={mode:'field',symbol:type==='gameover'?'rune':'star',count:18,size:18,color:type==='neon'?'#4de2e8':'#c9b8ff',spread:360,speed:3};project.layers.push(fx);selectLayer(text.id)}sceneChanged();toast('Composition preset создан')}

  installLayersUi();
  takeFile=addImageFile;
  $('#snapCenterBtn')?.addEventListener('click',()=>{v3SnapCenter=$('#snapCenterBtn').classList.contains('active')});
  $('#snapGridBtn')?.addEventListener('click',()=>{v3SnapGrid=$('#snapGridBtn').classList.contains('active')});
  document.querySelector('.stage-options')?.insertAdjacentHTML('beforeend','<label>Сцена <select id="canvasPreset"><option>1280×720</option><option>1920×1080</option><option>1080×1080</option><option>800×600</option><option>Custom</option></select></label>');
  document.querySelector('.stage-options')?.insertAdjacentHTML('beforeend','<label>FX <select id="particleQuality"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></label>');$('#particleQuality').value=project.settings.quality||'medium';$('#particleQuality').onchange=event=>{project.settings.quality=event.target.value;particles.items.length=0;saveScene();toast(`Качество FX: ${event.target.value}`)};
  $('#canvasPreset').value=project.canvas.preset||'1280×720';$('#canvasPreset').onchange=event=>{const value=event.target.value;if(value==='Custom'){openV3Dialog('Размер сцены','<div class="field-row"><input id="canvasW" type="number" min="100" max="4096" value="'+project.canvas.width+'"><input id="canvasH" type="number" min="100" max="4096" value="'+project.canvas.height+'"></div>',[{label:'Отмена',action:closeV3Dialog},{label:'Применить',primary:true,action:()=>{project.canvas.width=Math.max(100,Math.min(4096,+$('#canvasW').value));project.canvas.height=Math.max(100,Math.min(4096,+$('#canvasH').value));project.canvas.preset='Custom';closeV3Dialog();sceneChanged()}}])}else{const [w,h]=value.split('×').map(Number);project.canvas.width=w;project.canvas.height=h;project.canvas.preset=value;sceneChanged()}};
  $('#backgroundSelect').addEventListener('change',event=>{project.canvas.background={grid:'transparent',dark:'#08090d',gray:'#555555',white:'#f2f2f4'}[event.target.value]||'transparent';composition.style.background=project.canvas.background;saveScene()});composition.style.background=project.canvas.background==='transparent'?'transparent':project.canvas.background;
  $('#fileInput').onchange=e=>e.target.files[0]&&addImageFile(e.target.files[0]);$('#uploadBtn').onclick=$('#emptyUpload').onclick=()=>$('#fileInput').click();$('#demoBtn').onclick=()=>{const demo=demoAsset(),layer=baseLayer('image','Demo Crystal');layer.data={runtimeUrl:demo.url,width:220,height:260,displayWidth:220};layer.asset=demo.meta;project.layers.push(layer);blobUrls.set(layer.id,demo.url);selectLayer(layer.id);sceneChanged()};
  document.querySelectorAll('.tool-nav button').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.section==='layers')renderSelectedEditor()}));
  addEventListener('keydown',event=>{const modalOpen=!$('#modalBackdrop').classList.contains('hidden');if(event.key==='Escape'){if(modalOpen)closeV3Dialog();else{project.selectedLayerId=null;selectedIds.clear();renderScene()}return}if(modalOpen||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();restoreSceneHistory(event.shiftKey?sceneHistoryIndex+1:sceneHistoryIndex-1);return}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();restoreSceneHistory(sceneHistoryIndex+1);return}const layer=selected();if(!layer)return;if(event.key==='Delete'){event.preventDefault();deleteLayer(layer.id)}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'){event.preventDefault();duplicateLayer(layer.id)}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();saveScene(true);toast('Проект сохранён локально')}if(event.key.startsWith('Arrow')){event.preventDefault();const step=event.shiftKey?10:1;if(event.key==='ArrowLeft')layer.transform.x-=step;if(event.key==='ArrowRight')layer.transform.x+=step;if(event.key==='ArrowUp')layer.transform.y-=step;if(event.key==='ArrowDown')layer.transform.y+=step;sceneChanged()}});
  const previousChanged=changed;changed=function(){previousChanged();if(selected()&&config===selected()){particles.setConfig({...selected().particles,count:Math.round(selected().particles.count*({low:.45,medium:.75,high:1}[project.settings.quality]||.75))});renderScene();saveScene()}};
  $('#undoBtn').onclick=()=>restoreSceneHistory(sceneHistoryIndex-1);$('#redoBtn').onclick=()=>restoreSceneHistory(sceneHistoryIndex+1);
  const baseResetSection=resetSection;$('#resetSection').onclick=()=>{const layer=selected();if(section==='layers'&&layer){layer.transform={x:0,y:0,scale:1,rotation:0};layer.opacity=1;renderSelectedEditor();sceneChanged();toast('Трансформация слоя сброшена')}else baseResetSection()};
  document.querySelectorAll('[data-snapshot]').forEach(button=>{button.onclick=event=>{const key=button.dataset.snapshot;if(!sceneSnapshots[key]||event.shiftKey){sceneSnapshots[key]=cleanProject();button.textContent=`${key} · сцена`;toast(`Snapshot ${key} сохранён`);return}sceneHistoryLock=true;project=JSON.parse(JSON.stringify(sceneSnapshots[key]));window.galProject=project;project.layers.forEach(normalizeLayer);const layer=selected();if(layer)config=layer;renderScene();renderSelectedEditor();sceneHistoryLock=false;document.querySelectorAll('[data-snapshot]').forEach(x=>x.classList.toggle('active',x===button));toast(`Показана сцена ${key}`)}});
  const originalButton=$('#originalBtn');if(originalButton){originalButton.onpointerdown=()=>{const layer=selected(),node=composition.querySelector(`[data-layer-id="${layer?.id}"]`);if(node){node.querySelector('.layer-content').style.filter='none';node.querySelector('.layer-anim').style.animation='none';originalButton.classList.add('active')}};const restoreOriginal=()=>{originalButton.classList.remove('active');renderScene()};originalButton.onpointerup=restoreOriginal;originalButton.onpointerleave=restoreOriginal}
  $('#resetProject').onclick=()=>openV3Dialog('Сбросить композицию?','<p>Все слои, настройки и локальные файлы текущей сцены будут удалены.</p>',[{label:'Отмена',action:closeV3Dialog},{label:'Сбросить',primary:true,action:async()=>{for(const layer of project.layers)if(layer.data?.assetKey)await deleteBlob(layer.data.assetKey);project={version:3,name:'Новая композиция',canvas:{width:1280,height:720,preset:'1280×720',background:'transparent'},layers:[],selectedLayerId:null,settings:{quality:'medium',grid:10}};window.galProject=project;localStorage.removeItem(V3_KEY);closeV3Dialog();sceneChanged();toast('Композиция сброшена')}}]);
  pushSceneHistory();restoreUrls();renderScene();renderLayersPanel();if(project.selectedLayerId)selectLayer(project.selectedLayerId);saveScene();
})();
